<?php
declare(strict_types=1);
ini_set('display_errors','0');require __DIR__.'/server/exchange.php';
header('Content-Type: text/html; charset=UTF-8');header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');
session_set_cookie_params(['httponly'=>true,'samesite'=>'Strict','secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off']);session_start();$_SESSION['rss_csrf']??=bin2hex(random_bytes(24));
$e=static fn($s):string=>htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$fmtdate=static function(string $date):string {return $date===''?'Дата не указана':(new DateTimeImmutable($date))->setTimezone(new DateTimeZone('Europe/Moscow'))->format('d.m.Y H:i');};
$error='';$uploadError='';$preview=null;$cache=['items'=>[],'updated_at'=>'','checked_at'=>'','error'=>''];$items=[];$p=exchange_params([]);
try{
    $p=exchange_params($_GET);$own=exchange_own(db());
    try{$cache=rss_external(($_GET['refresh']??'')==='1');}catch(Throwable $ex){$cache['error']='Внешнюю ленту пока не удалось загрузить.';error_log('MIXLAB RSS cache unavailable');}
    $items=exchange_select(array_merge($own,$cache['items']),$p);
}catch(InvalidArgumentException $ex){http_response_code(422);$error=$ex->getMessage();}
catch(Throwable $ex){http_response_code(503);$error='Не удалось загрузить новости. Повтори позже.';error_log('MIXLAB RSS page: '.$ex->getMessage());}
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        if((int)($_SERVER['CONTENT_LENGTH']??0)>RSS_MAX_BYTES+16384){http_response_code(413);throw new InvalidArgumentException('Файл слишком большой. Максимум — 512 КБ.');}
        if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['rss_csrf'],$_POST['csrf'])){http_response_code(403);throw new InvalidArgumentException('Обнови страницу и снова выбери файл.');}
        $file=$_FILES['rss_file']??null;
        if(!is_array($file)||($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_string($file['tmp_name']??null)||!is_uploaded_file($file['tmp_name']))throw new InvalidArgumentException('Выбери доступный RSS-файл размером до 512 КБ.');
        $raw=file_get_contents($file['tmp_name'],false,null,0,RSS_MAX_BYTES+1);$preview=rss_parse($raw===false?'':$raw);$preview['items']=exchange_select($preview['items'],exchange_params([]));
    }catch(InvalidArgumentException $ex){if(http_response_code()===200)http_response_code(422);$uploadError=$ex->getMessage();}
    catch(Throwable $ex){http_response_code(422);$uploadError='Не удалось прочитать RSS-файл.';}
}
$total=count($items);$pages=max(1,(int)ceil($total/12));$page=min($p['page'],$pages);$visible=array_slice($items,($page-1)*12,12);
$url=static fn(array $changes):string=>'rss.html?'.http_build_query(array_merge($p,$changes),'','&',PHP_QUERY_RFC3986);
function rss_cards(array $items,callable $e,callable $fmtdate):void { ?>
<div class="rss-grid"><?php foreach($items as $x): ?><article class="rss-item" data-origin="<?= $e($x['origin']) ?>"><div class="rss-meta"><span class="rss-source"><?= $e($x['source']) ?></span><?php if($x['published_at']!==''): ?><time datetime="<?= $e($x['published_at']) ?>"><?= $e($fmtdate($x['published_at'])) ?></time><?php else: ?><span>Дата не указана</span><?php endif; ?></div><h3><?php if($x['link']!==''): ?><a href="<?= $e($x['link']) ?>"<?= $x['origin']!=='own'?' rel="noopener noreferrer"':'' ?>><?= $e($x['title']) ?></a><?php else: ?><?= $e($x['title']) ?><?php endif; ?></h3><?php if($x['description']!==''): ?><p><?= $e(exchange_text($x['description'],250)) ?><?= preg_match_all('/./us',$x['description'])>250?'…':'' ?></p><?php endif; ?><?php if($x['link']!==''): ?><a class="text-link" href="<?= $e($x['link']) ?>"<?= $x['origin']!=='own'?' rel="noopener noreferrer"':'' ?>><?= $x['origin']==='own'?'Читать новость':'Открыть источник' ?> →</a><?php endif; ?></article><?php endforeach; ?></div>
<?php }
ob_start(); ?>
<div class="rss-toolbar"><a class="btn primary" href="feed.php">RSS-подписка MIXLAB</a><a class="btn" href="services/news.html">Новости сайта</a><a class="btn" href="<?= $e($url(['refresh'=>'1'])) ?>">Обновить ленту</a></div>
<h2>Объединённая лента</h2>
<p class="rss-status">Новости сайта и заголовки <a class="text-link" href="https://www.soundonsound.com/news">Sound On Sound</a>. Внешние публикации открываются на сайте источника.</p>
<?php if($cache['updated_at']!==''): ?><p class="rss-status">Внешняя лента обновлена: <time datetime="<?= $e($cache['updated_at']) ?>"><?= $e($fmtdate($cache['updated_at'])) ?></time> МСК. Проверено: <?= $e($fmtdate($cache['checked_at'])) ?>. Автопроверка — раз в 15 минут при открытии страницы, ручная — не чаще раза в минуту.</p><?php endif; ?>
<?php if($cache['error']): ?><p class="notice" role="status"><?= $e($cache['updated_at']!==''?$cache['error']:'Внешний источник пока недоступен. Новости MIXLAB доступны ниже.') ?></p><?php endif; ?>
<?php if($error): ?><p class="notice" role="alert"><?= $e($error) ?></p><?php endif; ?>
<form class="rss-filter" action="rss.html" method="get"><label for="rss-query">Поиск по новостям<input id="rss-query" name="q" type="search" maxlength="120" value="<?= $e($p['q']) ?>" placeholder="Например, вокал или компрессор"></label><label for="rss-source">Источник<select id="rss-source" name="source"><?php foreach(['all'=>'Все источники','own'=>'MIXLAB','external'=>RSS_SOURCE_NAME] as $key=>$label): ?><option value="<?= $key ?>"<?= $p['source']===$key?' selected':'' ?>><?= $e($label) ?></option><?php endforeach; ?></select></label><label for="rss-sort">Порядок<select id="rss-sort" name="sort"><?php foreach(['newest'=>'Сначала новые','oldest'=>'Сначала старые','title'=>'По заголовку'] as $key=>$label): ?><option value="<?= $key ?>"<?= $p['sort']===$key?' selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><div class="actions"><button class="btn primary" type="submit">Показать</button><a class="btn" href="rss.html">Сбросить</a></div></form>
<p class="rss-count">Найдено новостей: <span id="rss-total"><?= $total ?></span></p>
<?php if(!$items): ?><p class="notice">Новостей по этим условиям пока нет. Попробуй изменить поиск или источник.</p><?php else:rss_cards($visible,$e,$fmtdate);endif; ?>
<?php if($pages>1): ?><nav class="rss-pagination" aria-label="Страницы новостей"><?php if($page>1): ?><a class="btn" href="<?= $e($url(['page'=>$page-1])) ?>">← Назад</a><?php endif; ?><span>Страница <?= $page ?> из <?= $pages ?></span><?php if($page<$pages): ?><a class="btn" href="<?= $e($url(['page'=>$page+1])) ?>">Далее →</a><?php endif; ?></nav><?php endif; ?>
<div class="rss-tools"><section aria-labelledby="rss-export"><h2 id="rss-export">Скачать новости</h2><p>Скачивается вся выборка с текущими поиском, источником и порядком.</p><div class="actions"><?php foreach(['rss'=>'RSS','csv'=>'CSV','xml'=>'XML','txt'=>'TXT','wrapped'=>'XML + TXT'] as $format=>$label):$query=http_build_query(['format'=>$format,'source'=>$p['source'],'q'=>$p['q'],'sort'=>$p['sort'],'download'=>'1'],'','&',PHP_QUERY_RFC3986); ?><a class="btn" href="feed.php?<?= $e($query) ?>"><?= $label ?></a><?php endforeach; ?></div><details><summary>Какой формат выбрать</summary><p>RSS — для новостного приложения. CSV — для таблиц, с разделителем «;» и кодировкой UTF-8. XML — отдельные поля каждой новости. TXT — текст ASCII с названиями полей и табуляцией; кириллица и переносы записаны обратимыми JSON-последовательностями. XML + TXT — тот же текст с описанием полей внутри XML.</p></details><details><summary>Адрес для RSS-приложения</summary><code><?= $e(NEWS_BASE.'feed.php') ?></code><p>Эта подписка содержит только собственные новости MIXLAB.</p></details></section>
<section aria-labelledby="rss-file"><h2 id="rss-file">Открыть RSS-файл</h2><p>Выбери RSS 2.0, чтобы увидеть новости из файла. Файл используется только для просмотра и не публикуется в общей ленте.</p><form class="rss-upload" action="rss.html#rss-preview" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?= $e($_SESSION['rss_csrf']) ?>"><label for="rss-file-input">RSS или XML, до 512 КБ<input id="rss-file-input" name="rss_file" type="file" accept=".xml,.rss,application/rss+xml,application/xml,text/xml" required></label><button class="btn" type="submit">Открыть файл</button></form></section></div>
<?php if($uploadError||$preview!==null): ?><section class="rss-preview" id="rss-preview" aria-labelledby="preview-title"><h2 id="preview-title">Новости из файла</h2><?php if($uploadError): ?><p class="notice" role="alert"><?= $e($uploadError) ?></p><?php else: ?><p><?= $e($preview['title']?:'RSS-лента') ?>. Записей: <?= count($preview['items']) ?>.<?php if($preview['skipped']): ?> Пропущено пустых записей и повторов: <?= $preview['skipped'] ?>.<?php endif; ?></p><?php if(count($preview['items'])>50): ?><p class="small">Показаны первые 50 записей из файла.</p><?php endif;rss_cards(array_slice($preview['items'],0,50),$e,$fmtdate);endif; ?></section><?php else: ?><div id="rss-preview"></div><?php endif; ?>
<?php
$fragment=ob_get_clean();$template=file_get_contents(__DIR__.'/rss.html');$a=strpos($template,'<!-- RSS:START -->');$b=strpos($template,'<!-- RSS:END -->');echo substr($template,0,$a+strlen('<!-- RSS:START -->')).$fragment.substr($template,$b);
